import { Flow, Handle, Position, useFlow } from '@pyreon/flow'
import type { NodeComponentProps } from '@pyreon/flow'

type Task = { label: string; status: 'todo' | 'done' }

// Runs once per node. The accessors keep it current on drag, select and updateNode.
const TaskNode = (props: NodeComponentProps<Task>) => (
  <div class={() => (props.selected() ? 'task selected' : 'task')}>
    <Handle type="target" position={Position.Left} />
    {() => props.data().label}
    {() => (props.data().status === 'done' ? ' (done)' : '')}
    <Handle type="source" position={Position.Right} />
  </div>
)

export const Board = () => {
  const flow = useFlow<Task>({
    nodes: [{ id: 't1', type: 'task', position: { x: 0, y: 0 }, data: { label: 'Write spec', status: 'todo' } }],
  })
  const finish = () => flow.updateNode('t1', { data: { label: 'Write spec', status: 'done' } })
  return (
    <>
      <button onClick={finish}>Mark done</button>
      <Flow instance={flow} nodeTypes={{ task: TaskNode }} />
    </>
  )
}

