import dagre from '@dagrejs/dagre'
import { ReactFlow, useEdgesState, useNodesState } from '@xyflow/react'
import type { Edge, Node } from '@xyflow/react'

// React Flow has no layout engine: the docs point you at dagre, elkjs or d3-hierarchy.
function layoutWithDagre(nodes: Node[], edges: Edge[]): Node[] {
  const g = new dagre.graphlib.Graph().setDefaultEdgeLabel(() => ({}))
  g.setGraph({ rankdir: 'LR', nodesep: 40, ranksep: 80 })
  for (const n of nodes) g.setNode(n.id, { width: n.measured?.width ?? 150, height: n.measured?.height ?? 40 })
  for (const e of edges) g.setEdge(e.source, e.target)
  dagre.layout(g)
  return nodes.map((n) => {
    const p = g.node(n.id)
    // dagre returns centres; React Flow positions are top-left corners.
    return { ...n, position: { x: p.x - p.width / 2, y: p.y - p.height / 2 } }
  })
}

export function Pipeline(props: { nodes: Node[]; edges: Edge[] }) {
  const [nodes, setNodes, onNodesChange] = useNodesState(props.nodes)
  const [edges, , onEdgesChange] = useEdgesState(props.edges)
  return (
    <>
      <button onClick={() => setNodes(layoutWithDagre(nodes, edges))}>Tidy up</button>
      <ReactFlow nodes={nodes} edges={edges} onNodesChange={onNodesChange} onEdgesChange={onEdgesChange} />
    </>
  )
}

