import { Background, Controls, Flow, Panel, useFlow } from '@pyreon/flow'

const KEY = 'my-diagram'

export const SavedDiagram = () => {
  // history off while restoring, so the first Undo cannot wipe the saved diagram
  const flow = useFlow({ nodes: [{ id: 'a', position: { x: 0, y: 0 }, data: { label: 'Idea' } }], autoHistory: false })
  const saved = localStorage.getItem(KEY)
  // fromJSON treats input as untrusted: duplicate ids and dangling edges are dropped with a warning.
  if (saved) flow.fromJSON(JSON.parse(saved))
  flow.config.autoHistory = true

  const save = () => localStorage.setItem(KEY, JSON.stringify(flow.toJSON()))
  return (
    <Flow instance={flow}>
      <Background />
      <Controls />
      <Panel position="top-right">
        <button onClick={save}>Save</button>
        <button onClick={() => flow.undo()}>Undo</button>
        <button onClick={() => flow.redo()}>Redo</button>
      </Panel>
    </Flow>
  )
}

import { Flow, MiniMap, createFlow } from '@pyreon/flow'
import type { Connection, FlowEdge, FlowInstance, FlowNode } from '@pyreon/flow'

type Step = { label: string; kind: 'trigger' | 'action' }

export function createWorkflow(nodes: FlowNode<Step>[], edges: FlowEdge[]) {
  const flow: FlowInstance<Step> = createFlow<Step>({
    nodes,
    edges,
    // A step cannot feed itself, and nothing may connect INTO a trigger.
    isValidConnection: (c: Connection) => c.source !== c.target && flow.nodeMap().get(c.target)?.data.kind !== 'trigger',
    defaultEdgeOptions: { type: 'smoothstep', animated: true },
    onlyRenderVisibleElements: true,
  })
  flow.onConnect((c) => console.log('connected', c.source, '->', c.target))
  return flow
}

export const Workflow = (props: { flow: FlowInstance<Step> }) => (
  <Flow instance={props.flow} ariaLabel="Workflow">
    <MiniMap />
  </Flow>
)
